    "explanation": "전구 양쪽이 같은 전지 단자에 이어져 있다. 전지 방향만 뒤집어도 접속 관계가 그대로이므로 전구는 켜지지 않는다. 한 전선을 다른 단자로 옮겨야 전구를 거치는 연결이 된다.",
