        "alt": "보기 상자 안에 ㄱ·ㄴ·ㄷ 세 회로가 위에서 아래로 놓여 있어요. 모두 전지 한 개와 전구 한 개를 이용해요. ㄱ과 ㄴ은 전지의 두 연결 단자에 빨간색·검은색 전선이 있고, 집게가 전구에 닿는 위치가 달라요. ㄷ은 세워진 전지 위에 전구가 닿아 있고 전선이 전구와 전지의 아래쪽을 이어요."
