    "prompt": "위 전기 회로 중 전구에 불이 켜지는 전기 회로의 특징으로 옳지 않은 것을 <보기>에서 골라 기호를 쓰세요.",
    "choices": null,
    "sourceContextBlocks": [
      {
        "type": "text",
        "text": "다음 전기 회로를 보고, 물음에 답하세요."
      },
      {
        "type": "figure",
        "src": "assets/bank/c22-s62-u03/legacy-s62-electricity-s4-basic-circuits.png",
        "alt": "ㄱ·ㄴ·ㄷ·ㄹ 네 칸의 회로예요. 모두 전지 한 개와 전구 한 개를 이용해요. ㄱ은 한 가닥 전선만 이어져 있어요. ㄴ과 ㄷ은 전지 양쪽에 빨간색·검은색 전선이 있고 집게가 전구에 닿는 위치가 달라요. ㄹ은 세워진 전지 위쪽에 전구가 닿아 있고 전선이 전구와 전지 아래쪽을 이어요."
      }
    ],
    "sourceMaterialBlocks": [
      {
        "type": "list",
        "items": [
          "가. 전류가 잘 흐르지 않는 부분끼리 연결되어 있습니다.",
          "나. 전지, 전선, 전구가 끊어지지 않고 연결되어 있습니다.",
          "다. 전구가 전지의 (+)극과 전지의 (-)극에 각각 연결되어 있습니다."
        ]
      }
    ],
